#include <cstddef>
#include <format>
#include <iostream>
#include <optional>
#include <span>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

using IndexPair = std::pair<std::ptrdiff_t, std::ptrdiff_t>;

[[nodiscard]] std::optional<IndexPair> nearby_repeat(std::span<const int> ids, std::ptrdiff_t k) {
  std::unordered_map<int, std::ptrdiff_t> last_seen;  // id -> its latest index so far
  for (std::ptrdiff_t j = 0; j < std::ssize(ids); ++j) {
    if (const auto it = last_seen.find(ids[j]); it != last_seen.end() && j - it->second <= k) {
      return IndexPair{it->second, j};
    }
    last_seen.insert_or_assign(ids[j], j);  // overwrite: the nearest earlier copy is the one that matters
  }
  return std::nullopt;
}

[[nodiscard]] std::string show(const std::optional<IndexPair>& pair) {
  return pair ? std::format("{{{}, {}}}", pair->first, pair->second) : "no value";
}

int main() {
  const std::vector<int> a{7, 3, 9, 3, 7};
  const std::vector<int> b{4, 1, 2, 3, 4, 4};
  const std::vector<int> c{5, 5};
  const std::vector<int> none;
  std::cout << std::format("{} {} {}\n", show(nearby_repeat(a, 2)), show(nearby_repeat(a, 1)), show(nearby_repeat(b, 1)));
  std::cout << std::format("k = 0: {}, empty: {}\n", show(nearby_repeat(c, 0)), show(nearby_repeat(none, 3)));
}

#include <array>
#include <cstddef>
#include <format>
#include <iostream>
#include <string_view>
#include <vector>

[[nodiscard]] std::vector<std::ptrdiff_t> anagram_starts(std::string_view text, std::string_view pattern) {
  std::vector<std::ptrdiff_t> starts;
  const std::ptrdiff_t m = std::ssize(pattern);
  if (m == 0 || m > std::ssize(text)) return starts;
  const auto slot = [](char c) { return static_cast<unsigned char>(c); };  // char may be negative
  std::array<std::ptrdiff_t, 256> need{};
  std::array<std::ptrdiff_t, 256> have{};  // byte counts of the window text[right - m + 1..right]
  for (const char c : pattern) ++need[slot(c)];
  for (std::ptrdiff_t right = 0; right < std::ssize(text); ++right) {
    ++have[slot(text[right])];
    if (right >= m) --have[slot(text[right - m])];  // the byte that leaves
    if (right >= m - 1 && have == need) starts.push_back(right - m + 1);
  }
  return starts;
}

struct Case {
  std::string_view text;
  std::string_view pattern;
};

int main() {
  const std::array<Case, 3> cases{{{.text = "abxbaaxab", .pattern = "ab"},
                                   {.text = "aaaa", .pattern = "aa"},
                                   {.text = "ab", .pattern = "abc"}}};
  for (const Case& c : cases) {
    std::cout << std::format("\"{}\" \"{}\":", c.text, c.pattern);
    for (const std::ptrdiff_t start : anagram_starts(c.text, c.pattern)) std::cout << ' ' << start;
    std::cout << '\n';
  }
}

#include <cstddef>
#include <cstdint>
#include <iostream>
#include <span>
#include <string_view>
#include <vector>

[[nodiscard]] std::vector<std::int64_t> sorted_squares(std::span<const int> errors) {
  std::vector<std::int64_t> out(errors.size());
  std::ptrdiff_t lo = 0;
  std::ptrdiff_t hi = std::ssize(errors) - 1;
  for (std::ptrdiff_t write = std::ssize(errors) - 1; write >= 0; --write) {  // an empty log: write is -1
    const std::int64_t left = std::int64_t{errors[lo]} * errors[lo];  // 64-bit: 46341 squared passes the int limit
    const std::int64_t right = std::int64_t{errors[hi]} * errors[hi];
    if (left > right) {
      out[write] = left;
      ++lo;
    } else {
      out[write] = right;
      --hi;
    }
  }
  return out;
}

int main() {
  const std::vector<std::vector<int>> logs{{-7, -3, 0, 2, 5}, {-2, -1}, {}, {-46341, 46341}};
  for (const std::vector<int>& log : logs) {
    const std::vector<std::int64_t> squares = sorted_squares(log);
    std::string_view separator;
    for (const std::int64_t square : squares) {
      std::cout << separator << square;
      separator = " ";
    }
    std::cout << (squares.empty() ? "(empty)\n" : "\n");
  }
}
